from django.db import migrations, models


def range_to_time_map(apps, schema_editor):
    """Eski "başlangıç–bitiş saati" aralığını tüm günleri kapsayan zaman haritasına çevirir."""
    CardRelationship = apps.get_model("timetable", "CardRelationship")
    for rel in CardRelationship.objects.select_related("school").exclude(period_from=None):
        start = max(1, rel.period_from) - 1
        end = (rel.period_to or rel.period_from) - 1
        rel.time_map = [f"{d}-{p}" for d in range(rel.school.days_per_week) for p in range(min(start, end), max(start, end) + 1)]
        rel.save(update_fields=["time_map"])


